<?php $title='Dự án'; ?>
<div class="page-head"><div><span class="eyebrow">WORKSPACE</span><h1>Dự án</h1><p>Quản lý dự án, thành viên và môi trường thử nghiệm.</p></div></div>
<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Dự án của bạn</h2><p><?= count($projects) ?> dự án</p></div></div><?php if(!$projects): ?><p class="empty">Bạn chưa có dự án nào.</p><?php else: ?><div class="project-list"><?php foreach($projects as $project): ?><div class="project-card"><div><strong><?= e($project['name']) ?></strong><small><?= e($project['key']) ?> · <?= e($project['role']) ?></small></div><form method="post" action="<?= e(url('projects/switch')) ?>"><?= csrf_field() ?><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><input type="hidden" name="environment_id" value="0"><input type="hidden" name="return_to" value="projects"><button class="button" type="submit">Mở →</button></form><?php if(($user['account_type']??'')==='owner'): ?><form method="post" action="<?= e(url('projects/delete')) ?>" onsubmit="return confirm('Xóa dự án này và thu hồi API key của dự án?')"><?= csrf_field() ?><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><button class="button danger small" type="submit">Xóa</button></form><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?></section>
<?php if(($user['account_type']??'')==='owner'): ?><section class="panel"><div class="panel-head"><div><h2>Tạo dự án</h2><p>Ứng dụng tự tạo môi trường, tính năng có sẵn và API key riêng.</p></div></div><form method="post" action="<?= e(url('projects/create')) ?>" class="form-grid"><?= csrf_field() ?><label>Tên dự án<input name="name" required maxlength="160" placeholder="Ví dụ: Mobile App"></label><label>Project key<input name="key" maxlength="80" placeholder="mobile-app"></label><label class="wide">Mô tả<textarea name="description" rows="3"></textarea></label><button class="button primary" type="submit">Tạo dự án</button></form></section><?php endif; ?></div>
<?php if($activeProjectId && $canManageProjectKey): ?><section class="panel"><div class="panel-head"><div><h2>API key riêng của dự án · <?= e($activeProject['name'] ?? '') ?></h2><p>Key chỉ đọc và chỉ áp dụng cho dự án đang chọn; có thể chọn môi trường trong request.</p></div></div><?php if($newAccountApiKey): ?><div class="notice success">API key của dự án (chỉ hiển thị lần này): <code><?= e($newAccountApiKey) ?></code></div><?php endif; ?><?php if($accountApiKey): ?><p>Prefix: <code><?= e($accountApiKey['key_prefix']) ?></code> · <?= $accountApiKey['last_used_at']?'dùng gần nhất '.e($accountApiKey['last_used_at']):'chưa sử dụng' ?></p><?php else: ?><p class="muted">Dự án chưa có API key riêng.</p><?php endif; ?><?php if(App\Support\Auth::isAdmin($activeProjectId)): ?><form method="post" action="<?= e(url('account/api-key/rotate')) ?>"><?= csrf_field() ?><button class="button primary" type="submit"><?= $accountApiKey?'Đổi API key dự án':'Tạo API key dự án' ?></button></form><?php endif; ?></section><?php endif; ?>
<?php if($activeProjectId): ?><section class="panel"><div class="panel-head"><div><h2>Môi trường &amp; API keys</h2><p>Key môi trường cũ vẫn hỗ trợ; key riêng tài khoản nằm ở mục phía trên.</p></div></div><?php if($newApiKey): ?><div class="notice success">API key môi trường mới (chỉ hiển thị lần này): <code><?= e($newApiKey) ?></code></div><?php endif; ?><?php foreach($environments as $environment): ?><?php $envKey=null; foreach($keys as $apiKey) if((int)$apiKey['environment_id']===(int)$environment['id']) {$envKey=$apiKey;break;} ?><div class="group-row"><div><strong><?= e($environment['name']) ?></strong><small><code><?= e($environment['key']) ?></code> · <?php if($envKey): ?>Key prefix <?= e($envKey['key_prefix']) ?> · <?= $envKey['last_used_at']?'dùng gần nhất '.e($envKey['last_used_at']):'chưa sử dụng' ?><?php else: ?>Chưa có API key<?php endif; ?></small></div><?php if(App\Support\Auth::isAdmin($activeProjectId)): ?><form method="post" action="<?= e(url('api-keys/rotate')) ?>"><?= csrf_field() ?><input type="hidden" name="environment_id" value="<?= (int)$environment['id'] ?>"><button class="button small" type="submit">Tạo / đổi key</button></form><?php endif; ?></div><?php endforeach; ?><?php if(App\Support\Auth::isAdmin($activeProjectId)): ?><details class="details-form"><summary>Thêm môi trường</summary><form method="post" action="<?= e(url('environments/create')) ?>" class="form-grid"><?= csrf_field() ?><label>Tên môi trường<input name="name" required></label><label>Environment key<input name="key" required pattern="[a-z][a-z0-9_-]{1,79}"></label><button class="button" type="submit">Tạo môi trường</button></form></details><?php endif; ?></section><?php endif; ?>
